#!/usr/bin/env bash
# cloudnative-pg/cloudnative-pg 0.29.0 - base variant: default
# Path: pull the package, render this base variant locally, read the objects,
# then apply them with kubectl. No ConfigHub account is needed.
# Generated by scripts/generate-public-site.mjs from the committed package
# data for this base variant. Chart page: https://confighub.github.io/helm-expt/site/charts/cloudnative-pg-cloudnative-pg-0-29-0.html
set -euo pipefail

say() { printf '\n>> %s\n' "$*"; }

if ! command -v cub >/dev/null 2>&1; then
  printf 'cub is not installed. Install the cub CLI with:\n  curl -fsSL https://hub.confighub.com/cub/install.sh | bash\nthen add ~/.confighub/bin to your PATH and re-run this script.\n' >&2
  exit 1
fi

# Installer is a cub plugin. Check it before this script does any work.
if ! cub installer --help >/dev/null 2>&1; then
  printf 'The cub installer plugin is missing. Follow https://confighub.github.io/helm-expt/site/try.html#install-cub, then re-run this script.\n' >&2
  exit 1
fi

if ! command -v kustomize >/dev/null 2>&1; then
  printf 'kustomize is missing. Follow https://confighub.github.io/helm-expt/site/try.html#install-cub, then re-run this script.\n' >&2
  exit 1
fi

if ! command -v kubectl >/dev/null 2>&1; then
  printf 'kubectl is required for the apply step.\n' >&2
  exit 1
fi

say "Pull the package and render the default base variant into ./cloudnative-pg-cloudnative-pg-0-29-0-default"
cub installer setup --pull oci://ghcr.io/confighub/packages/cloudnative-pg:v0.29.0@sha256:0b81eaf4a0ef721ee0f3d1f5dadb5fa801dd3bf60c6948079fac4f2c183749ef --base default --work-dir ./cloudnative-pg-cloudnative-pg-0-29-0-default --non-interactive --namespace cnpg-system

say "Read what was rendered; nothing has touched the cluster yet"
ls ./cloudnative-pg-cloudnative-pg-0-29-0-default/out/manifests

say "Ensure the cnpg-system namespace exists"
kubectl create namespace cnpg-system --dry-run=client -o yaml | kubectl apply -f -

if [ -d ./cloudnative-pg-cloudnative-pg-0-29-0-default/out/secrets ]; then
  say "Apply rendered Secrets first"
  kubectl apply -f ./cloudnative-pg-cloudnative-pg-0-29-0-default/out/secrets
fi

say "Apply the rendered objects"
kubectl apply -f ./cloudnative-pg-cloudnative-pg-0-29-0-default/out/manifests

say "Done. The cluster received exactly the files in ./cloudnative-pg-cloudnative-pg-0-29-0-default/out."
